import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { once } from "node:events";
import * as http from "node:http";
import type { AddressInfo } from "node:net";
import type { Duplex } from "node:stream";
import { fileURLToPath } from "node:url";

import { WebSocketServer } from "ws";

import { writePattern } from "../../support/preview-bytes.ts";

/**
 * The workspace dev servers the preview gateway is tested against, plain `node:http`:
 *
 * - `digest`: any method and path; hashes the body as it streams and answers
 *   `{ method, path, bytes, sha256, headers }`. `?rate=<bytes per second>` reads slowly.
 * - `download`: `GET /bytes?n=<count>` streams `n` generated bytes with Content-Length,
 *   `&chunked=1` without it.
 * - `sse`: `GET /events?every=<ms>&count=<n>` flushes `count` events `every` ms apart, the first at
 *   once; each event's data is `{ i, sentAt }` (epoch ms).
 * - `websocket`: echoes every message on any upgrade path; `/upgrade-refused` answers a plain 400.
 * - `cookies`: `GET /set-cookies` sets the cookies in `FIXTURE_COOKIES` and a Clear-Site-Data
 *   header; `GET /echo-headers` answers `{ headers, rawHeaders }` as it saw them.
 * - `all`: every route above on one port, the digest sink for any other path.
 */

export type FixtureKind = "digest" | "download" | "sse" | "websocket" | "cookies" | "all";

export interface DigestAnswer {
  readonly method: string;
  readonly path: string;
  readonly bytes: number;
  readonly sha256: string;
  readonly headers: http.IncomingHttpHeaders;
}

export interface SseEvent {
  readonly i: number;
  readonly sentAt: number;
}

export interface EchoedHeaders {
  readonly headers: http.IncomingHttpHeaders;
  readonly rawHeaders: ReadonlyArray<readonly [string, string]>;
}

export const FIXTURE_COOKIES = [
  "plain=1; Path=/",
  "scoped=2; Domain=localhost; Path=/",
  "dated=3; Expires=Wed, 21 Oct 2037 07:28:00 GMT; Path=/",
  "secret=4; HttpOnly; Path=/",
  "__Host-mend-preview=from-the-app; Secure; Path=/",
] as const;

export const FIXTURE_CLEAR_SITE_DATA = '"cookies", "storage"';

type RequestHandler = (request: http.IncomingMessage, response: http.ServerResponse) => void;
type UpgradeHandler = (request: http.IncomingMessage, socket: Duplex, head: Buffer) => void;

interface FixtureApp {
  readonly request: RequestHandler;
  readonly upgrade?: UpgradeHandler;
}

const queryOf = (request: http.IncomingMessage) =>
  new URL(request.url ?? "/", "http://fixture.invalid").searchParams;

const pathOf = (request: http.IncomingMessage) => (request.url ?? "/").split("?")[0] ?? "/";

const numberParam = (params: URLSearchParams, name: string, fallback: number) => {
  const value = Number(params.get(name) ?? Number.NaN);
  return Number.isFinite(value) && value >= 0 ? value : fallback;
};

const json = (response: http.ServerResponse, status: number, body: unknown) => {
  const text = JSON.stringify(body);
  response.writeHead(status, {
    "content-type": "application/json",
    "content-length": Buffer.byteLength(text),
  });
  response.end(text);
};

const digest: FixtureApp = {
  request: (request, response) => {
    const rate = numberParam(queryOf(request), "rate", 0);
    const hash = createHash("sha256");
    let bytes = 0;
    const started = performance.now();
    request.on("data", (chunk: Buffer) => {
      hash.update(chunk);
      bytes += chunk.length;
      if (rate === 0) return;
      // Paced against the start, so timer granularity never lowers the average rate.
      const ahead = started + (bytes / rate) * 1000 - performance.now();
      if (ahead < 1) return;
      request.pause();
      setTimeout(() => request.resume(), ahead);
    });
    request.on("end", () => {
      const answer: DigestAnswer = {
        method: request.method ?? "",
        path: request.url ?? "",
        bytes,
        sha256: hash.digest("hex"),
        headers: request.headers,
      };
      json(response, 200, answer);
    });
  },
};

const download: FixtureApp = {
  request: (request, response) => {
    if (pathOf(request) !== "/bytes") return json(response, 404, { error: "not found" });
    const params = queryOf(request);
    const bytes = numberParam(params, "n", 0);
    response.writeHead(200, {
      "content-type": "application/octet-stream",
      ...(params.get("chunked") === "1" ? {} : { "content-length": String(bytes) }),
    });
    void writePattern(response, bytes);
  },
};

const sse: FixtureApp = {
  request: (request, response) => {
    if (pathOf(request) !== "/events") return json(response, 404, { error: "not found" });
    const params = queryOf(request);
    const every = numberParam(params, "every", 1000);
    const count = numberParam(params, "count", 3);
    response.writeHead(200, {
      "content-type": "text/event-stream",
      "cache-control": "no-store",
    });
    response.flushHeaders();
    let i = 0;
    const send = () => {
      if (response.destroyed) return;
      const event: SseEvent = { i, sentAt: Date.now() };
      response.write(`id: ${i}\ndata: ${JSON.stringify(event)}\n\n`);
      i += 1;
      if (i >= count) response.end();
      else timer = setTimeout(send, every);
    };
    let timer = setTimeout(send, 0);
    response.once("close", () => clearTimeout(timer));
  },
};

const refuseUpgrade = (socket: Duplex) => {
  const body = "upgrade refused";
  socket.end(
    `HTTP/1.1 400 Bad Request\r\nContent-Type: text/plain\r\nContent-Length: ${body.length}\r\nConnection: close\r\n\r\n${body}`,
  );
};

const echoServer = new WebSocketServer({ noServer: true });
echoServer.on("connection", (client) => {
  client.on("message", (data, isBinary) => client.send(data, { binary: isBinary }));
});

const echoUpgrade: UpgradeHandler = (request, socket, head) => {
  if (pathOf(request) === "/upgrade-refused") return refuseUpgrade(socket);
  echoServer.handleUpgrade(request, socket, head, (client) =>
    echoServer.emit("connection", client, request),
  );
};

const websocket: FixtureApp = {
  request: (request, response) =>
    pathOf(request) === "/upgrade-refused"
      ? json(response, 400, { error: "upgrade refused" })
      : json(response, 426, { error: "upgrade required" }),
  upgrade: echoUpgrade,
};

const rawHeaderPairs = (request: http.IncomingMessage) =>
  request.rawHeaders.flatMap(
    (value, index, all): Array<readonly [string, string]> =>
      index % 2 === 0 ? [[value, all[index + 1] ?? ""]] : [],
  );

const cookies: FixtureApp = {
  request: (request, response) => {
    const path = pathOf(request);
    if (path === "/set-cookies") {
      response.setHeader("set-cookie", [...FIXTURE_COOKIES]);
      response.setHeader("clear-site-data", FIXTURE_CLEAR_SITE_DATA);
      return json(response, 200, { set: FIXTURE_COOKIES });
    }
    if (path === "/echo-headers") {
      const echoed: EchoedHeaders = {
        headers: request.headers,
        rawHeaders: rawHeaderPairs(request),
      };
      return json(response, 200, echoed);
    }
    json(response, 404, { error: "not found" });
  },
};

const ROUTES_OF_ALL: ReadonlyArray<readonly [string, FixtureApp]> = [
  ["/bytes", download],
  ["/events", sse],
  ["/set-cookies", cookies],
  ["/echo-headers", cookies],
  ["/upgrade-refused", websocket],
];

const all: FixtureApp = {
  request: (request, response) => {
    const path = pathOf(request);
    const app = ROUTES_OF_ALL.find(([route]) => route === path)?.[1] ?? digest;
    app.request(request, response);
  },
  upgrade: echoUpgrade,
};

const APPS: Record<FixtureKind, FixtureApp> = {
  digest,
  download,
  sse,
  websocket,
  cookies,
  all,
};

export interface RunningFixture {
  readonly port: number;
  readonly stop: () => Promise<void>;
}

export const serveFixture = async (kind: FixtureKind, port = 0): Promise<RunningFixture> => {
  const app = APPS[kind];
  const server = http.createServer({ requestTimeout: 0, keepAliveTimeout: 60_000 }, app.request);
  const upgrade = app.upgrade;
  if (upgrade === undefined) server.on("upgrade", (_request, socket) => refuseUpgrade(socket));
  else server.on("upgrade", upgrade);
  server.listen(port, "127.0.0.1");
  await once(server, "listening");
  const address: AddressInfo | string | null = server.address();
  if (address === null || typeof address === "string") throw new Error("no TCP address");
  return {
    port: address.port,
    stop: async () => {
      server.closeAllConnections();
      await new Promise<void>((resolve) => server.close(() => resolve()));
    },
  };
};

const CHILD_ENTRY = fileURLToPath(new URL("./serve.ts", import.meta.url));

/**
 * Serves one fixture in a child Node process, so its memory is not the caller's, on an ephemeral
 * (or the given) port. The child prints `{"port":N}` once listening and exits on SIGTERM.
 */
export const spawnFixture = async (kind: FixtureKind, at = 0): Promise<RunningFixture> => {
  const child = spawn(
    process.execPath,
    ["--experimental-strip-types", CHILD_ENTRY, kind, String(at)],
    { stdio: ["ignore", "pipe", "inherit"] },
  );
  const exited = once(child, "exit");
  const port = await new Promise<number>((resolve, reject) => {
    let seen = "";
    child.stdout.setEncoding("utf8");
    child.stdout.on("data", (text: string) => {
      seen += text;
      const line = seen.split("\n")[0];
      if (!seen.includes("\n") || line === undefined) return;
      const parsed: unknown = JSON.parse(line);
      if (typeof parsed === "object" && parsed !== null && "port" in parsed) {
        const value: unknown = parsed.port;
        if (typeof value === "number") return resolve(value);
      }
      reject(new Error(`unexpected fixture output: ${line}`));
    });
    child.once("exit", (code) => reject(new Error(`fixture exited (${code}) before listening`)));
  });
  return {
    port,
    stop: async () => {
      if (child.exitCode === null && child.signalCode === null) child.kill("SIGTERM");
      await exited;
    },
  };
};
